'use strict';
const SUBJECTS=[
 {id:'history',title:'Lịch sử Đảng',category:'Đại cương',code:'HIS',tag:'Ngân hàng đầy đủ',tone:'rose',desc:'Nắm dòng sự kiện. Hiểu từ khóa. Tự tin từng câu hỏi.',topics:['362 câu hỏi','3 chương','Gợi ý & giọng đọc'],count:'362 câu hỏi',search:'lich su dang dai cuong chinh tri'},
 {id:'information',title:'Lý thuyết truyền tin',category:'Chuyên ngành',code:'INF',tag:'Nội dung nhập môn',tone:'mint',desc:'Từ lượng tin đến mã hóa. Xây nền tảng trước khi giải bài.',topics:['Entropy & lượng tin','Mã nguồn','Mã kiểm soát lỗi'],count:'4 bài nền tảng',search:'ly thuyet truyen tin entropy shannon fano hamming crc'},
 {id:'ai',title:'Khoa học dữ liệu & Trí tuệ nhân tạo',category:'Công nghệ',code:'AI',tag:'Nội dung nhập môn',tone:'lilac',desc:'Hiểu dữ liệu, cách mô hình học và cách đánh giá kết quả.',topics:['Dữ liệu','Học máy','Đánh giá mô hình'],count:'4 bài nền tảng',search:'khoa hoc du lieu tri tue nhan tao ai machine learning'}
];
const LESSONS={
 information:[
  {title:'Lượng tin & entropy',lead:'Sự kiện càng ít có khả năng xảy ra, lượng tin khi biết nó xảy ra càng lớn.',formula:'I(x) = −log₂ p(x) · H(X) = −Σ p(x) log₂ p(x)',body:'Với nguồn nhị phân đồng xác suất, mỗi ký hiệu mang 1 bit thông tin và entropy bằng 1 bit/ký hiệu. Entropy là lượng tin trung bình, không phải lượng tin của một sự kiện riêng lẻ.',remember:'Phân biệt: I(x) cho một sự kiện; H(X) cho cả nguồn.',example:'Nếu p(x) = 1/4 thì I(x) = 2 bit. Nếu p(x) = 1 thì I(x) = 0 bit.'},
  {title:'Mã nguồn & hiệu quả mã',lead:'Mã nguồn biểu diễn các ký hiệu bằng chuỗi bit, thường nhằm giảm độ dài trung bình.',formula:'L̄ = Σ pᵢlᵢ · η = H(X) / L̄',body:'Mã tiền tố không có từ mã nào là phần đầu của từ mã khác, nên có thể giải mã tức thời. Với mã Huffman nhị phân tối ưu trong lớp mã tiền tố, H(X) ≤ L̄ < H(X) + 1.',remember:'Nguồn xác suất cao thường nhận từ mã ngắn hơn.',example:'Với xác suất 1/2, 1/4, 1/4, mã 0, 10, 11 có độ dài trung bình 1,5 bit/ký hiệu.'},
  {title:'Khoảng cách Hamming',lead:'Khoảng cách giữa hai từ nhị phân là số vị trí có bit khác nhau.',formula:'Phát hiện tối đa dmin − 1 lỗi · Sửa tối đa ⌊(dmin − 1)/2⌋ lỗi',body:'Khoảng cách tối thiểu dmin của bộ mã quyết định khả năng bảo vệ. Thêm bit dư giúp các từ mã hợp lệ cách xa nhau hơn, nhưng làm tăng số bit truyền.',remember:'Phát hiện và sửa lỗi là hai khả năng khác nhau.',example:'1011 và 1101 khác nhau ở 2 vị trí, nên khoảng cách Hamming bằng 2.'},
  {title:'Dung lượng kênh & giới hạn Shannon',lead:'Dung lượng là giới hạn tốc độ truyền tin tin cậy của một mô hình kênh xác định.',formula:'Kênh AWGN: C = B log₂(1 + S/N)',body:'B tính bằng Hz; S/N là tỷ số công suất dạng tuyến tính; C tính bằng bit/s. Công thức này áp dụng cho kênh nhiễu Gaussian trắng cộng với các giả thiết tương ứng, không phải mọi kênh.',remember:'Nếu SNR cho bằng dB: S/N = 10^(SNRdB/10).',example:'B = 1.000 Hz, S/N = 3 ⇒ C = 1.000 × log₂4 = 2.000 bit/s.'}
 ],
 ai:[
  {title:'Dữ liệu, đặc trưng & nhãn',lead:'Một bài toán tốt bắt đầu từ câu hỏi rõ ràng và dữ liệu phù hợp.',formula:'Dữ liệu đầu vào X → mô hình → dự đoán ŷ',body:'Đặc trưng là thông tin mô hình sử dụng để dự đoán. Nhãn là kết quả mục tiêu trong học có giám sát. Cần xem chất lượng dữ liệu: giá trị thiếu, ngoại lệ, trùng lặp và cách thu thập.',remember:'Không phải càng nhiều cột thì mô hình càng tốt.',example:'Dự đoán giá nhà: diện tích, vị trí là đặc trưng; giá bán thực tế là nhãn.'},
  {title:'Ba cách học thường gặp',lead:'Chọn phương pháp theo dạng dữ liệu và mục tiêu, không chỉ theo tên thuật toán.',formula:'Có giám sát · Không giám sát · Tăng cường',body:'Học có giám sát dùng dữ liệu có nhãn để dự đoán. Học không giám sát tìm cấu trúc trong dữ liệu chưa có nhãn mục tiêu. Học tăng cường tối ưu hành động thông qua phần thưởng trong quá trình tương tác.',remember:'Phân loại dự đoán lớp; hồi quy dự đoán đại lượng số.',example:'Phát hiện thư rác là phân loại; dự đoán nhiệt độ là hồi quy; chia nhóm khách hàng có thể là phân cụm.'},
  {title:'Train, validation & test',lead:'Đánh giá đúng nghĩa là thử trên dữ liệu chưa được dùng để học hoặc lựa chọn mô hình.',formula:'Train: học · Validation: lựa chọn · Test: đánh giá cuối',body:'Tránh rò rỉ dữ liệu: các bước như chuẩn hóa phải được khớp trên tập train rồi áp dụng sang validation/test. Với chuỗi thời gian, cần chia theo thứ tự thời gian phù hợp thay vì xáo trộn tùy tiện.',remember:'Không dùng điểm test để tinh chỉnh lặp đi lặp lại.',example:'Một mô hình làm rất tốt trên train nhưng kém trên dữ liệu mới có thể đang quá khớp.'},
  {title:'Đánh giá & sử dụng có trách nhiệm',lead:'Một con số accuracy cao chưa đủ chứng minh mô hình hữu ích.',formula:'Precision = TP/(TP+FP) · Recall = TP/(TP+FN)',body:'Với dữ liệu lệch lớp, nên xem ma trận nhầm lẫn và chỉ số phù hợp mục tiêu. Đồng thời kiểm tra quyền riêng tư, thiên lệch dữ liệu, giới hạn sử dụng và khả năng giải thích kết quả.',remember:'Chỉ số phải phản ánh chi phí của từng loại sai lầm.',example:'Nếu 99% mẫu là lớp âm, mô hình luôn đoán âm vẫn đạt 99% accuracy nhưng không tìm được mẫu dương nào.'}
 ]
};
let subjectQuery='',subjectCategory='all',activeSubject='information';
function academyIcon(name){const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',book:'<path d="M12 6C8 3 4 4 2 5v14c4-2 7-1 10 1 3-2 6-3 10-1V5c-4-2-7-1-10 1v14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',check:'<path d="m5 12 4 4L19 6"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-9 10 9 5 9-5M3 18l9 5 9-5"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;}
function courseCards(){const list=SUBJECTS.filter(s=>(subjectCategory==='all'||s.category===subjectCategory)&&normalize(s.title+' '+s.search).includes(normalize(subjectQuery)));return `<p class="catalog-count" role="status">${list.length} môn học phù hợp</p><div class="course-grid">${list.map(s=>`<article class="course-card"><div class="course-art ${s.tone}"><span class="course-status">${s.tag}</span><span class="course-number">0${SUBJECTS.indexOf(s)+1}</span><div class="course-illustration" aria-hidden="true">${academyIcon(s.id==='ai'?'spark':s.id==='information'?'layers':'book')}<span>${s.code}</span></div><span class="art-label">KIẾN HỌC / ${s.code}</span></div><div class="course-content"><span class="course-category">${s.category}</span><h3>${s.title}</h3><p>${s.desc}</p><div class="course-tags">${s.topics.map(t=>`<span>${t}</span>`).join('')}</div><div class="course-bottom"><span>${s.count}<small>Truy cập miễn phí</small></span><button class="course-open" data-course="${s.id}" aria-label="Mở môn ${s.title}">${academyIcon('arrow')}</button></div></div></article>`).join('')}</div>${list.length?'':`<div class="empty"><h3>Chưa tìm thấy môn học</h3><p>Thử “truyền tin”, “AI” hoặc “lịch sử”.</p><button class="btn" data-clear-courses>Xóa tìm kiếm</button></div>`}`;}
function catalogPage(){return `<section class="academy-hero"><div class="hero-copy"><div class="academy-kicker"><span></span> KHÔNG GIAN HỌC TẬP ĐẠI HỌC</div><h1>Học có hướng.<br>Nhớ <em>có cách.</em></h1><p>Biến kiến thức dài thành từng bước nhỏ.<br>Chọn môn bạn cần, học điều cốt lõi và luyện tập theo nhịp của mình.</p><a href="#course-library" class="academy-cta">Khám phá môn học ${academyIcon('arrow')}</a><div class="hero-promises"><span>${academyIcon('check')} Không cần đăng ký</span><span>${academyIcon('check')} Miễn phí hiện tại</span></div></div><div class="hero-board" aria-label="Lộ trình học: hiểu ý chính, luyện tập, ôn lại"><div class="board-top"><span>HỌC ÍT MỘT. HIỂU SÂU HƠN.</span>${academyIcon('spark')}</div><div class="study-stack"><div class="stack-tab">PHƯƠNG PHÁP KIẾN HỌC</div><h2>Một bài học.<br>Ba bước ghi nhớ.</h2><div class="board-step"><b>01</b><span>Hiểu ý chính<small>Nắm từ khóa, nối kiến thức</small></span>${academyIcon('check')}</div><div class="board-step"><b>02</b><span>Thử sức<small>Áp dụng vào từng câu hỏi</small></span>${academyIcon('arrow')}</div><div class="board-step"><b>03</b><span>Ôn đúng chỗ<small>Quay lại phần còn vướng</small></span>${academyIcon('arrow')}</div></div><div class="board-note">Một chút mỗi ngày. Một bước vững hơn.</div></div></section><section class="academy-strip"><div><b>03</b><span>Môn học để khám phá</span></div><div><b>362</b><span>Câu Lịch sử Đảng</span></div><div><b>08</b><span>Bài nền tảng ở 2 môn mới</span></div><div><b>Theo nhịp bạn</b><span>Học trên máy tính & điện thoại</span></div></section>${saved.session?`<section class="continue-card"><div>${academyIcon('book')}<span><b>Lượt ôn Lịch sử Đảng đang chờ bạn</b><small>Tiếp tục từ câu bạn đã dừng, không cần bắt đầu lại.</small></span></div><button class="btn primary" id="resume">Tiếp tục học ${academyIcon('arrow')}</button></section>`:''}<section id="course-library" class="course-library"><div class="library-heading"><div><div class="academy-kicker">THƯ VIỆN MÔN HỌC</div><h2>Hôm nay, bạn muốn học gì?</h2></div><span>Chọn một môn. Bắt đầu một bước.</span></div><div class="course-toolbar"><label class="course-search">${academyIcon('search')}<span class="sr-only">Tìm kiếm môn học</span><input id="subject-search" type="search" placeholder="Tìm môn học, chủ đề…" value="${esc(subjectQuery)}"></label><div class="category-tabs" role="group" aria-label="Lọc theo nhóm môn">${['all','Đại cương','Chuyên ngành','Công nghệ'].map(c=>`<button data-category="${c}" aria-pressed="${subjectCategory===c}" class="${subjectCategory===c?'active':''}">${c==='all'?'Tất cả môn học':c}</button>`).join('')}</div></div><div id="course-results">${courseCards()}</div></section><section class="method-section"><div><div class="academy-kicker">ĐƯỢC THIẾT KẾ ĐỂ BẠN HỌC THẬT</div><h2>Không chỉ là một danh sách đáp án.</h2><p>Mỗi môn có một cách tiếp cận rõ ràng, để bạn biết mình đang học gì và nên đi đâu tiếp theo.</p></div><div class="method-grid"><article>${academyIcon('spark')}<h3>Nổi bật điều quan trọng</h3><p>Từ khóa và mốc cốt lõi được tô sáng trong bộ câu hỏi Lịch sử Đảng.</p></article><article>${academyIcon('book')}<h3>Nghe theo nhịp của bạn</h3><p>Giọng đọc tiếng Việt và tốc độ tùy chỉnh cho câu hỏi, phương án.</p></article><article>${academyIcon('layers')}<h3>Học theo lớp kiến thức</h3><p>Từ nền tảng đến phân biệt, không cần ôm mọi thứ cùng một lúc.</p></article><article>${academyIcon('check')}<h3>Biết rõ nguồn nội dung</h3><p>Phân biệt bộ đề tài liệu và bài nhập môn; không hứa hẹn điểm thi.</p></article></div></section><section class="academy-bottom"><span>MỘT KHỞI ĐẦU NHỎ, MỘT BƯỚC TIẾN DÀI.</span><h2>Bắt đầu với điều bạn cần hiểu.</h2><a class="academy-cta" href="#course-library">Chọn môn học ${academyIcon('arrow')}</a></section>`;}
function lessonKey(i){return activeSubject+':'+i;}
function readLessons(){try{return JSON.parse(localStorage.getItem('kienhoc-lessons-v1'))||{};}catch{return{};}}
function subjectPage(){return home();}
function academyShell(){const catalog=view==='catalog',subject=view==='subject';document.body.classList.toggle('academy-mode',catalog||subject);const brand=document.querySelector('.brand');brand.setAttribute('aria-label','Kiến Học, thư viện môn học');brand.innerHTML='<img class="brandmark brand-mascot" src="assets/kienhoc-mascot.png" alt="" aria-hidden="true" width="48" height="48"><span>Kiến Học<small>HỌC CÓ HƯỚNG, NHỚ CÓ CÁCH</small></span>';let nav=document.querySelector('[data-catalog-nav]');if(!nav){nav=document.createElement('button');nav.className='nav';nav.dataset.catalogNav='';nav.innerHTML=academyIcon('layers')+'<span>Khám phá môn học</span>';document.querySelector('nav').prepend(nav);}nav.classList.toggle('active',catalog);document.querySelector('header').innerHTML=`<span>KIẾN HỌC <i>/</i> <strong>${catalog?'Khám phá môn học':subject?SUBJECTS.find(s=>s.id===activeSubject).title:subjectTitle()}</strong></span><button class="header-library" data-catalog>Thư viện môn học ${academyIcon('arrow')}</button>`;document.querySelector('footer').innerHTML='<div class="academy-footer"><b>Kiến Học<span>Học có hướng, nhớ có cách.</span></b><span>Không gian học tập độc lập · Miễn phí hiện tại<br>Tiến độ lưu riêng trên trình duyệt, chưa đồng bộ tài khoản.</span><button class="btn link" data-catalog>Khám phá môn học ↑</button></div>';document.querySelector('.navlabel').textContent='THƯ VIỆN & GÓC ÔN TẬP';}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('.brand,[data-catalog],[data-catalog-nav]')){e.preventDefault();e.stopImmediatePropagation();subjectQuery='';subjectCategory='all';go('catalog');window.scrollTo(0,0);}else if(t.dataset.course){e.stopImmediatePropagation();openSubject(t.dataset.course);window.scrollTo(0,0);}else if(t.dataset.category){subjectCategory=t.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t));});document.querySelector('#course-results').innerHTML=courseCards();window.KienPolish?.refreshCourses();}else if('clearCourses'in t.dataset){subjectQuery='';document.querySelector('#subject-search').value='';document.querySelector('#course-results').innerHTML=courseCards();window.KienPolish?.refreshCourses();}else if('lesson'in t.dataset){const key=lessonKey(Number(t.dataset.lesson)),done=readLessons();done[key]=!done[key];try{localStorage.setItem('kienhoc-lessons-v1',JSON.stringify(done));window.KienCloud?.queue();t.textContent=done[key]?'✓ Đã đọc xong — Bỏ đánh dấu':'Đánh dấu đã đọc xong';t.setAttribute('aria-pressed',String(done[key]));t.classList.toggle('primary',!done[key]);t.closest('details').querySelector('summary small').textContent=done[key]?'Đã đánh dấu đọc xong':'Bài nền tảng · Có ví dụ';document.querySelector('.lesson-progress').textContent=LESSONS[activeSubject].filter((_,i)=>done[lessonKey(i)]).length+'/4 bài đã đọc';}catch{toast('Không thể lưu trạng thái bài đọc trên trình duyệt này.');}}},true);
document.addEventListener('input',e=>{if(e.target.id==='subject-search'){subjectQuery=e.target.value;document.querySelector('#course-results').innerHTML=courseCards();window.KienPolish?.refreshCourses();}});
